        storyId: spec.storyId,
        agentType: spec.agentType,
        phase: spec.phase,
        promptText,
        reviewRunId: spec.reviewRunId,
        lane: spec.lane,
        timeoutMs: Math.min(spec.timeoutMs, remainingMs),
        signal: abort.signal,
        agyPrintTimeout: spec.agyPrintTimeout ?? undefined,
