function resolveStoryPhaseForUsage(ctx: HandlerContext, storyId: string): string {
  try {
    const phase = ctx.store.readStory(storyId)?.phase;
    return typeof phase === 'string' && phase.length > 0 ? phase : 'adhoc';
  } catch {
    return 'adhoc';
  }
}

